(function(window,document,undefined){"use strict";var clickOpt="click",hoverOpt="hover",toggleMethod="data-mfb-toggle",menuState="data-mfb-state",isOpen="open",isClosed="closed",mainButtonClass="mfb-component__button--main";var elemsToClick,elemsToHover,mainButton,target,currentState;function attachEvt(elems,evt){for(var i=0,len=elems.length;i<len;i++){mainButton=elems[i].querySelector("."+mainButtonClass);mainButton.addEventListener(evt,toggleButton,false)}}function replaceAttrs(elems){for(var i=0,len=elems.length;i<len;i++){elems[i].setAttribute(toggleMethod,clickOpt);elems[i].setAttribute(menuState,isClosed)}}function getElemsByToggleMethod(selector){return document.querySelectorAll("["+toggleMethod+'="'+selector+'"]')}function toggleButton(evt){target=evt.target;while(target&&!target.getAttribute(toggleMethod)){target=target.parentNode;if(!target){return}}currentState=target.getAttribute(menuState)===isOpen?isClosed:isOpen;target.setAttribute(menuState,currentState)}if(window.Modernizr&&Modernizr.touch){elemsToHover=getElemsByToggleMethod(hoverOpt);replaceAttrs(elemsToHover)}elemsToClick=getElemsByToggleMethod(clickOpt);attachEvt(elemsToClick,"click")})(window,document);